    "text.report.emoticons": "Convert rule-matched emoticons to words before character filtering: :) → 'cười', :( → 'buồn', ^^ → 'vui'. Only matched patterns are converted.",
    "text.report.teencode": "Replace informal spellings via dictionary: ko/k/kh → 'không', dc/đc → 'được', sp → 'sản phẩm', dt/đt → 'điện thoại'. Rules preserve exact semantics before feature extraction.",
    "text.report.characters": "Filter characters outside letters/digits/underscore, whitespace, and , . ? !; collapse whitespace. Retain Vietnamese diacritics and negation. Stopword removal is skipped to keep negation signals.",
    "text.report.cleaning-count": "After cleaning, the original set retains 5,100 development samples and 1,050 test samples. The Augmented set contains 10,149 samples created via round-trip back-translation (Vietnamese → English → Vietnamese), doubling syntactic diversity.",
    "text.report.branches-title": "Three input representation branches",
    "text.report.inputs.caption": "Preprocessing comparison across TF-IDF, Word2Vec, and PhoBERT",
