    "text.report.inputs.row.0.0": "Development data",
    "text.report.inputs.row.0.1": "Base: 5,100 cleaned samples. Augmented: 10,149 samples (Vi→En→Vi back-translation).",
    "text.report.inputs.row.0.2": "Base: 5,100 cleaned samples. Augmented: 10,149 samples (Vi→En→Vi back-translation).",
    "text.report.inputs.row.0.3": "Base: 5,100 cleaned samples. Augmented: 10,149 samples (Vi→En→Vi back-translation).",
    "text.report.inputs.row.1.0": "Segmentation / Vocabulary",
