    "text.report.inputs.row.1.2": "Remove ASCII digits; PyVi segmentation. Vocab fitted on train, queried via 400-dim vi-model-CBOW.",
    "text.report.inputs.row.1.3": "NFC normalization, emoticon/teencode mapping; BPE subword tokenization via vinai/phobert-base-v2.",
    "text.report.inputs.row.2.0": "Representation & Length",
    "text.report.inputs.row.2.1": "Sparse matrix (N, 5000) for LinearSVC; dense tensor reshaped to (N, 1, 5000) for 1D-CNN.",
